#define LL_T long long
#define DBL_T double
#define PAIR_T pair<int, int>
#define MK make_pair
#define SE second
#define FI first
using namespace std;
const int MAXN = 5005;
const int MAXE = 4 * MAXN * sqrt(MAXN);
const int INF_VAL = 1e9;
struct flowData { int c, f; };
int n, m, k, c, d, s, t, total, pre[MAXN];
int head[MAXN], edgeIdx = 1;
struct Edge {
	int to, next, val, w;
} e[MAXE << 1];
void connectEdge(int u, int v, int val, int w) {
	++edgeIdx;
	e[edgeIdx].next = head[u];
	e[edgeIdx].w = w;
	e[edgeIdx].to = v;
	e[edgeIdx].val = val;
	head[u] = edgeIdx;
}
void addEdgePair(int u, int v, int val, int w) {
	connectEdge(u, v, val, w);
	connectEdge(v, u, 0, -w);
}
int dist[MAXN]; bool inQueue[MAXN];
bool spfa() {
	std::fill(dist + 1, dist + total + 1, INF_VAL);
	std::queue<int> q;
	q.push(s);
	dist[s] = 0;
	while(!q.empty()) {
		int u = q.front(); q.pop();
		inQueue[u] = false;
		for(int i = head[u]; i; i = e[i].next) {
