					q.push(v);
				}
			}
		}
	}
	return dist[t] < INF_VAL;
}
flowData minCostFlow() {
	flowData totalFlow = {0, 0};
	while(spfa()) {
		int flowCap = INF_VAL;
		for(int x = t; x != s; x = e[pre[x] ^ 1].to)
			flowCap = min(flowCap, e[pre[x]].val);
		for(int x = t; x != s; x = e[pre[x] ^ 1].to) {
			e[pre[x]].val -= flowCap;
			e[pre[x] ^ 1].val += flowCap;
		}
		totalFlow.f += flowCap;
		totalFlow.c += dist[t] * flowCap;
	}
	return totalFlow;
